/**
 * One-time generator: fetches Roboto Regular + Bold + Italic TTFs (all Greek-capable)
 * from a stable mirror and writes a jsPDF-compatible JS module that registers all
 * three style variants on any jsPDF instance.
 *
 * Run with:  node scripts/generate-pdf-fonts.mjs
 *   (or:    npm run build:fonts)
 *
 * The generated file is committed to the repo so production builds never
 * touch the network. Re-run only if you want to refresh the font.
 */

import { mkdir, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const PRIMARY_BASE  = 'https://cdn.jsdelivr.net/gh/googlefonts/roboto@main/src/hinted/';
const FALLBACK_BASE = 'https://raw.githubusercontent.com/googlefonts/roboto/main/src/hinted/';

const FONTS = [
  { variant: 'Regular', style: 'normal', file: 'Roboto-Regular.ttf' },
  { variant: 'Bold',    style: 'bold',   file: 'Roboto-Bold.ttf'    },
  { variant: 'Italic',  style: 'italic', file: 'Roboto-Italic.ttf'  },
];

const OUT_DIR  = path.join(__dirname, '..', 'src', 'assets', 'fonts');
const OUT_FILE = path.join(OUT_DIR, 'Roboto-Regular-normal.js'); // kept name for import compatibility

async function fetchTtf(file) {
  try {
    const resp = await fetch(PRIMARY_BASE + file);
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    return Buffer.from(await resp.arrayBuffer());
  } catch (err) {
    console.warn(`Primary fetch failed for ${file}: ${err.message} — trying fallback`);
    const resp = await fetch(FALLBACK_BASE + file);
    if (!resp.ok) throw new Error(`Fallback fetch failed (${resp.status}) for ${file}`);
    return Buffer.from(await resp.arrayBuffer());
  }
}

async function main() {
  const fetched = [];
  for (const f of FONTS) {
    console.log(`Fetching ${f.file}…`);
    const ttf = await fetchTtf(f.file);
    console.log(`  ${ttf.byteLength.toLocaleString()} bytes`);
    fetched.push({ ...f, base64: ttf.toString('base64') });
  }

  const exports = fetched
    .map(f => `export const ROBOTO_${f.variant.toUpperCase()}_BASE64 = '${f.base64}';`)
    .join('\n\n');

  const registrations = fetched
    .map(f => {
      const vfsName = `Roboto-${f.variant}-${f.style}.ttf`;
      const exportName = `ROBOTO_${f.variant.toUpperCase()}_BASE64`;
      return `  doc.addFileToVFS('${vfsName}', ${exportName});
  doc.addFont('${vfsName}', 'Roboto', '${f.style}');`;
    })
    .join('\n');

  const js = `/* eslint-disable */
/**
 * Auto-generated by scripts/generate-pdf-fonts.mjs — do not edit.
 *
 * Roboto Regular + Bold + Italic base64 TTFs (Greek-capable) + helper.
 * Call registerRobotoFont(doc) once after \`new jsPDF()\` so subsequent
 * doc.setFont('Roboto', 'normal' | 'bold' | 'italic') calls render with the
 * correct visual weight AND support Greek (and other Unicode) characters.
 * The default Helvetica is Latin-only.
 */

${exports}

export function registerRobotoFont(doc) {
${registrations}
}
`;

  await mkdir(OUT_DIR, { recursive: true });
  await writeFile(OUT_FILE, js, 'utf8');
  console.log(`Wrote ${OUT_FILE} (${(js.length / 1024).toFixed(1)} KB)`);
}

main().catch(err => {
  console.error('Font generation failed:', err);
  process.exit(1);
});
